function dropHandler(e, setFile, setFileName) {
    e.preventDefault();
    [
        ...e.dataTransfer.items
    ].forEach((item)=>{
        if (item.kind === "file") {
            const fileObj = item.getAsFile();
            if (fileObj) {
                setFile(fileObj); // store actual File
                setFileName(fileObj.name);
            }
        }
    });
}
function onFileChange(e, setFile, setFileName) {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
        setFile(selectedFile); // store actual File
        setFileName(selectedFile.name);
    }
}
function dragHandler(e, output) {
    e.preventDefault();
    if (output.current) {
        output.current.style.borderColor = "blue";
    }
}
function dragLeaveHandler(e, output) {
    e.preventDefault();
    if (output.current) {
        output.current.style.borderColor = "grey";
    }
}
